import { isOverdue } from './dates.mjs';
import { PRIORITIES, normalizeTag } from './task.mjs';

const PRIORITY_RANK = Object.fromEntries(PRIORITIES.map((p, i) => [p, i]));

export function filterTasks(tasks, { status, tag, priority, overdue, now = new Date() } = {}) {
  const wanted = tag ? normalizeTag(tag) : null;
  return tasks.filter((task) => {
    if (status && status !== 'all' && task.status !== status) return false;
    if (wanted && !task.tags.includes(wanted)) return false;
    if (priority && task.priority !== priority) return false;
    if (overdue && !isOverdue(task, now)) return false;
    return true;
  });
}

const SORTERS = {
  id: (a, b) => a.id - b.id,
  due: (a, b) => (a.due === b.due ? 0 : a.due === null ? 1 : b.due === null ? -1 : a.due < b.due ? -1 : 1),
  priority: (a, b) => PRIORITY_RANK[b.priority] - PRIORITY_RANK[a.priority],
  title: (a, b) => a.title.localeCompare(b.title)
};

// Stable sort; ties keep ID order.
export function sortTasks(tasks, key = 'id') {
  const compare = SORTERS[key];
  if (!compare) throw new Error(`Unknown sort key: ${key}`);
  return [...tasks].sort((a, b) => compare(a, b) || a.id - b.id);
}

// Pages are numbered from 1.
export function paginate(items, page = 1, size = 20) {
  if (!Number.isInteger(page) || page < 1) throw new Error('Page must be a positive integer');
  if (!Number.isInteger(size) || size < 1 || size > 100) throw new Error('Page size must be between 1 and 100');
  const start = (page - 1) * size;
  return { items: items.slice(start, start + size), page, pages: Math.max(1, Math.ceil(items.length / size)), total: items.length };
}

import path from 'node:path';

/**
 * Resolve a relative path below the workspace root and return the absolute result as a string.
 * Works on path strings only - no filesystem access required.
 * @param {string} root - The workspace root directory (absolute path)
 * @param {string} value - The relative path to resolve
 * @returns {string} The absolute path
 * @throws {Error} If value is absolute or escapes the root via ../
 */
export function resolveRelative(root, value) {
  const rootAbs = path.resolve(root);
  const input = String(value || '.');

  // Check if value is an absolute path
  if (path.isAbsolute(input)) {
    throw new Error('Path escapes the workspace: ' + input);
  }

  // Resolve the target path
  const target = path.resolve(rootAbs, input);

  // Use path.relative to check if target escapes root
  const relative = path.relative(rootAbs, target);

  // If relative starts with '..' or is '..', it escapes the root
  if (relative.startsWith('..' + path.sep) || relative === '..' || path.isAbsolute(relative)) {
    throw new Error('Path escapes the workspace: ' + input);
  }

  return target;
}
